using System.IO;
using System.Runtime.InteropServices;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.PixelFormats;
using SixLabors.ImageSharp.Processing;

namespace PhotoView.Services;

/// <summary>
/// ストリームをフリーズ済みの BitmapSource にデコードします。
/// WPF標準（png/jpg/bmp/gif/tiff）と ImageSharp フォールバック（webp等）に対応。
/// </summary>
public static class ImageDecoder
{
    /// <summary>
    /// ストリームをデコードしてフリーズ済み BitmapSource を返します。失敗時は null。
    /// </summary>
    /// <param name="stream">画像データ。</param>
    /// <param name="maxWidth">0以外の場合、サムネイル用にこの幅以下に縮小してデコード。</param>
    public static BitmapSource? Decode(Stream stream, int maxWidth = 0)
    {
        // WPF の BitmapImage は StreamSource を非同期で読み込むため、
        // 呼び出し側のストリームを後で破棄すると競合が起きる。
        // 事前にバイト配列へ完全コピーし、専用の MemoryStream から読む。
        byte[] bytes;
        using (var ms = new MemoryStream())
        {
            stream.CopyTo(ms);
            bytes = ms.ToArray();
        }

        try
        {
            return DecodeWpf(bytes, maxWidth);
        }
        catch
        {
            try
            {
                return DecodeImageSharp(bytes, maxWidth);
            }
            catch
            {
                return null;
            }
        }
    }

    private static BitmapSource? DecodeWpf(byte[] bytes, int maxWidth)
    {
        var bi = new BitmapImage();
        bi.BeginInit();
        bi.CacheOption = BitmapCacheOption.OnLoad;
        bi.CreateOptions = BitmapCreateOptions.PreservePixelFormat;
        if (maxWidth > 0)
            bi.DecodePixelWidth = maxWidth;
        bi.StreamSource = new MemoryStream(bytes);
        bi.EndInit();
        bi.Freeze();
        return bi;
    }

    private static BitmapSource? DecodeImageSharp(byte[] bytes, int maxWidth)
    {
        using var stream = new MemoryStream(bytes);
        using var image = Image.Load<Bgra32>(stream);

        if (maxWidth > 0 && image.Width > maxWidth)
        {
            double ratio = (double)maxWidth / image.Width;
            int w = Math.Max(1, (int)(image.Width * ratio));
            int h = Math.Max(1, (int)(image.Height * ratio));
            image.Mutate(x => x.Resize(w, h));
        }

        if (!image.DangerousTryGetSinglePixelMemory(out var mem))
            return null;

        var pixelBytes = MemoryMarshal.AsBytes(mem.Span).ToArray();
        var bmp = BitmapSource.Create(
            image.Width, image.Height, 96, 96,
            PixelFormats.Bgra32, null, pixelBytes, image.Width * 4);
        bmp.Freeze();
        return bmp;
    }
}

