        Topmost = true;
    }
    else
    {
        WindowStyle = WindowStyle.SingleBorderWindow;
        WindowState = WindowState.Normal;
        Topmost = false;
        CloseFullscreenButton.Visibility = Visibility.Collapsed;
    }
    if (_isFit) FitToWindow();
}

